declare(strict_types=1);

namespace App\Modules\Blog\Domain;

/**
 * Kafka contract of the Blog module: topic blog.events (key = blog id → per-record
 * ordering), event types and the payload written to the transactional outbox by BlogService.
 */
final class BlogEvent
{
    public const TOPIC = 'blog.events';
    public const AGGREGATE = 'blog';
    public const SCHEMA_VERSION = 1;

    public const CREATED = Blog::EVENT_CREATED;
    public const UPDATED = Blog::EVENT_UPDATED;
    public const STATUS_CHANGED = Blog::EVENT_STATUS_CHANGED;
    public const DELETED = Blog::EVENT_DELETED;

    public const ALL = [self::CREATED, self::UPDATED, self::STATUS_CHANGED, self::DELETED];

    /**
     * Event payload = event-specific data + identifying attributes consumers usually need.
     *
     * @param array<string,mixed> $data
     * @return array<string,mixed>
     */
    public static function payload(Blog $entity, array $data): array
    {
        return $data + [
            'tenant_id' => $entity->tenantId,
            'title' => $entity->displayTitle(),
            'status' => $entity->status()->value,
            'version' => $entity->version(),
        ];
    }

    /** Human-readable one-liner for timelines. */
    public static function summary(string $type, array $payload): string
    {
        $title = (string) ($payload['title'] ?? 'blog');
        return match ($type) {
            self::CREATED => sprintf('Blog "%s" created', $title),
            self::UPDATED => sprintf('Blog "%s" updated: %s', $title, implode(', ', array_keys((array) ($payload['changes'] ?? [])))),
            self::STATUS_CHANGED => sprintf('Status changed %s → %s', $payload['from'] ?? '?', $payload['to'] ?? '?'),
            self::DELETED => sprintf('Blog "%s" deleted', $title),
            default => $type,
        };
    }
}
